ories": {"category_name": "人文社會"}, "smart_cabinets": {"cabinet_id": 5, "cabinet_name": "程曦嘍", "address": "100臺北市中正區青島東路", "open_time": "1970-01-01T00:00:00.000Z", "close_time": "1970-01-01T23:59:00.000Z", "latitude": "25.0428225", "longitude": "121.5248626"}, "in_cabinet": false}, {"book_id": 122, "seller_id": 7, "isbn": "9789864777075", "title": "生死之間", "author": "柯文哲", "publisher": "商周出版", "publish_date": "2019-08-29", "category_id": 1, "condition_level": "good", "condition_note": null, "price": "300", "quantity": 1, "description": "本書從急重症外科醫師柯文哲的臨床經驗出發，記錄他在急診室與加護病房中面對生死的觀察與思考。書中談及醫療救治的界線、生命末期的善終選擇，以及醫師、病人與家屬如何在艱難時刻溝通，並反思醫療資源分配與生命倫理等議題。\n\n作者也回望自己的行事方式與價值觀，呈現從醫療現場走向政治戰場的思考脈絡。適合對醫療人文、生死議題、生命倫理，以及柯文哲個人經歷與公共事務有興趣的讀者。", "cabinet_id": 5, "status": "on_sale", "view_count": 4, "is_approved": true, "share_token": null, "created_at": "2026-10-01T05:44:49.000Z", "updated_at": "2026-10-06T22:47:53.000Z", "users": {"user_id": 7, "nickname": "KJ", "avatar_url": "/uploads/avatars/1789557418447-043efa23c1c6426b.png"}, "book_images": [{"image_id": 259, "image_url": "/uploads/books/1790833488476-c837a4c3f755ac1a.png", "image_type": "cover"}, {"image_id": 260, "image_url": "/uploads/books/1790833488487-50d4fb663a2f80c5.png", "image_type": "back"}, {"image_id": 261, "image_url": "/uploads/books/1790833488496-0c38c52a69e6421c.png", "image_type": "other"}], "book_categories": {"category_name": "人文社會"}, "smart_cabinets": {"cabinet_id": 5, "cabinet_name": "程曦嘍", "address": "100臺北市中正區青島東路", "open_time": "1970-01-01T00:00:00.000Z", "close_time": "1970-01-01T23:59:00.000Z", "latitude": "25.0428225", "longitude": "121.5248626"}, "in_cabinet": false}, {"book_id": 121, "seller_id": 7, "isbn": "9789865065089", "title": "讓自己更快樂的情緖課", "author": "高井祐子", "publisher": "高寶書版", "publish_date": "2022-01-01", "category_id": 9, "condition_level": "like_new", "condition_note": null, "price": "350", "quantity": 1, "description": "本書介紹認知行為療法的基本觀念，說明情緒與心理、身體、認知及行為之間的關係，並引導讀者辨識自身的思考模式與情緒反應。內容以恐慌、憂鬱、社交恐懼症及強迫症