"category_id": 9, "category_name": "生活休閒", "parent_id": null, "sort_order": 2, "created_at": "2026-03-25T01:05:44.000Z", "other_book_categories": []}, {"category_id": 2, "category_name": "專業資訊", "parent_id": null, "sort_order": 3, "created_at": "2026-03-25T01:05:44.000Z", "other_book_categories": []}, {"category_id": 3, "category_name": "藝術設計", "parent_id": null, "sort_order": 4, "created_at": "2026-03-25T01:05:44.000Z", "other_book_categories": []}, {"category_id": 4, "category_name": "商業管理", "parent_id": null, "sort_order": 5, "created_at": "2026-03-25T01:05:44.000Z", "other_book_categories": []}, {"category_id": 5, "category_name": "自然科學", "parent_id": null, "sort_order": 6, "created_at": "2026-03-25T01:05:44.000Z", "other_book_categories": []}, {"category_id": 6, "category_name": "語言學習", "parent_id": null, "sort_order": 7, "created_at": "2026-03-25T01:05:44.000Z", "other_book_categories": []}, {"category_id": 8, "category_name": "文學小說", "parent_id": null, "sort_order": 8, "created_at": "2026-03-25T01:05:44.000Z", "other_book_categories": []}, {"category_id": 10, "category_name": "其他", "parent_id": null, "sort_order": 9, "created_at": "2026-03-25T01:05:44.000Z", "other_book_categories": []}], "faqs": [{"faq_id": 4, "category": "account", "question": "忘記密碼怎麼辦？", "answer": "請至登入頁點選「忘記密碼」，或透過「聯絡我們」開立工單由客服協助。", "sort_order": 0, "is_visible": true, "created_at": "2026-09-10T21:04:43.000Z", "updated_at": "2026-09-10T21:04:43.000Z"}, {"faq_id": 1, "category": "trade", "question": "書賣出後要多久存書？", "answer": "訂單成立後請於 7 日內把書放入指定書櫃，逾期訂單會自動取消並全額退款給買家。訂單內的書籍皆已於下單前存入訂單指定的書櫃時，訂單成立即為已存書，不需再存書；僅部分書籍先行存入時，其餘書籍仍須於 7 日內存入。", "sort_order": 0, "is_visible": true, "created_at": "2026-09-10T21:04:43.000Z", "updated_at": "2026-09-29T07:20:00.000Z"}, {"faq_id": 2, "category": "trade", "question": "買家沒有取書怎麼辦？", "answer": "訂單成為已存書後 7 日內未取書（訂單成立即為已存書者，自訂單成立起算），訂單會自動取消並全額退款給買家，書籍改為下架。書籍仍存放於書櫃，賣家須至書櫃以 App 掃描 QR Code 取回後才能重新上架；書櫃離線或故障時可改為手動回報取回，經客服確認後生效。", "sort_order": 1, "is_visible": true, "created_at": "2026-09-10T21:04:43.000Z", "updated_at": "2026-09-29T07:20:14.000Z"}, {"faq_id": 5, "category": "trade", "question": "上架後可以先把書放進書櫃嗎？", "answer": "可以。書籍上架後即可先行存書：至該書指定的書櫃，以 App 掃描書櫃螢幕上的 QR Code 存書；訂單內的書籍皆已先行存入訂單指定的書櫃時，買家下單後可直接取書。存書滿 7 天仍未售出會暫停販售，請至書櫃以 App 掃描 QR Code 取回，取回後書籍自動恢復上架；滿 14 天仍未取回者，平台得派員取出並下架，並代為保管 30 天；請於期間內聯絡客服，至指定地點免費領回或申請寄回（運費由賣家負擔，貨到付款），逾期未領回視為拋棄。書櫃離線或故障時，存書與取回可改為手動回報，經客服確認後生效。", "sort_order": 4, "is_visible": true, "created_at": "2026-09-29T07:21:05.000Z", "updated_at": "2026-09-29T07:21:05.000Z"}, {"faq_id": 3, "category": "wallet", "question": "代幣要怎麼取得？", "answer": "完成銷售後款項會撥入代幣餘額，也可以由客服協助儲值。", "sort_order": 0, "is_visible": true, "created_at": "2026-09-10T21:04:43.000Z", "updated_at": "2026-09-10T21:04:43.000Z"}], "announcements": [{"announcement_id": 6, "admin_id": 7, "title": "🆕 全新版本現已推出 請立即更新", "content": "新版本 1.0.3(10)", "type": "maintenance", "is_published": true, "published_at": "2026-09-17T07:58:49.000Z", "expires_at": null, "created_at": "2026-09-17T07:58:49.000Z", "updated_at": "2026-09-17T07:58:49.000Z", "users": {"user_id": 7, "nickname": "KJ"}}, {"announcement_id": 5, "admin_id": 11, "title": "您已被移除管理員權限", "content": "陳秉鴻說的算", "type": "policy", "is_published": true, "published_at": "2026-09-15T04:42:08.000Z", "expires_at": null, "created_at": "2026-09-15T04:42:08.000Z", "updated_at": "2026-09-15T04:42:08.000Z", "users": {"user_id": 11, "nickname": "Gary"}}, {"announcement_id": 4, "admin_id": 7, "title": "陳秉鴻道歉", "content": "我要求陳秉鴻道歉 並且給我轉帳10000元 當作我的生日禮物", "type": "maintenance", "is_published": true, "published_at": "2026-09-14T10:56:39.000Z", "expires_at": null, "created_at": "2026-09-14T10:56:39.000Z", "updated_at": "2026-09-14T10:56:39.000Z", "users": {"user_id": 7, "nickname": "KJ"}}], "legal": [{"doc_id": 3, "doc_key": "about", "title": "關於我們", "updated_at": "2026-09-10T21:04:43.000Z", "version": 1, "requires_consent": false}, {"doc_id": 4, "doc_key": "terms", "title": "服務條款", "updated_at": "2026-09-29T07:22:47.000Z", "